#include "Arduino_stub.h"
SerialT Serial;
static unsigned long T = 0;
unsigned long millis(){return T;} void delay(unsigned long ms){T+=ms;} void pinMode(int,int){} void digitalWrite(int,int){} int digitalRead(int){return 1;} int analogRead(int){return 0;} void analogSetAttenuation(int){}
#include "fw.cpp" // generated by run_tests.sh from ../esp32-sim900a-firmware.ino
int pass=0, fail=0;
void ok(bool c,const char*d){ c?pass++:fail++; printf("%s %s\n", c?"PASS":"FAIL", d); }
void advance(unsigned long sec){ for(unsigned long i=0;i<sec;i+=10){ T+=10000; schedulerTick(); } }
int main(){
  // reply parsing
  String rep("{\"t\":1763251200,\"cfg\":\"1,1,30;1,1080,590,30\",\"trh\":812.5,\"r1\":\"OFF\"}");
  ok(replyString(rep,"cfg")=="1,1,30;1,1080,590,30", "reply cfg parsed");
  ok((long)replyNumber(rep,"t",0)==1763251200L && replyNumber(rep,"trh",-1)==812.5, "reply time and run hours parsed");
  // clock: 2025-11-16 00:00 UTC = 05:30 IST
  oxyInit(oxy); oxyParseConfig("1,1,30;1,1080,590,30", oxyCfg);   // 6:00 PM - 9:50 AM
  epochBase = 1763251200UL; epochBaseMs = T; timeValid = true;
  ok(nowMinIST() == 330, "IST minute of day from server clock");
  advance(60);
  ok(generatorState, "inside overnight window at 5:30 AM: machine starts (catch-up)");
  ok(pendRunEvent=="START" && pendTrigger=="SCHEDULE", "start reported once as SCHEDULE");
  pendRunEvent=""; pendTrigger="";
  advance(4*3600 + 20*60);  // to 9:51 AM
  ok(!generatorState && pendRunEvent=="STOP", "stops at 9:50 AM stop time");
  pendRunEvent=""; pendTrigger="";
  advance(8*3600 + 10*60);  // to 6:01 PM
  ok(generatorState, "starts at 6:00 PM");
  advance(6*3600 + 60);     // 6 h later
  ok(!generatorState && oxy.resting && pendTrigger=="REST", "rests after 6 h continuous");
  ok(pendDurationSec >= 6*3600 - 30 && pendDurationSec <= 6*3600 + 90, "rest stop reports ~6 h run duration");
  pendRunEvent=""; pendTrigger="";
  advance(31*60);
  ok(generatorState && !oxy.resting, "restarts after 30 min rest inside the window");
  // manual OFF from app holds inside window
  stopGeneratorSequence("test"); oxyManual(oxy,false); advance(600);
  ok(!generatorState, "app OFF respected inside the window");
  // rest without clock still ends
  oxyInit(oxy); timeValid=false; oxyParseConfig("0,1,30", oxyCfg); T=1000000;
  startGeneratorSequence("t"); oxyManual(oxy,true); lastSchedTickMs=T;
  advance(6*3600+20); ok(oxy.resting && !generatorState, "no clock: still rests after 6 h");
  advance(31*60); ok(generatorState, "no clock: restarts after rest (no schedules)");
  printf("\nTOTAL %d | PASSED %d | FAILED %d\n", pass+fail, pass, fail);
  return fail?1:0;
}
